  OPTIMAL_UNSATURATED: { id: 'optimal_unsaturated', label: 'Optimal Unsaturated Suction', maxTheta: 0.30, color: '#22c55e', badgeClass: 'bg-green-500/20 text-green-300 border-green-500/30' },
