  SATURATED_LIQUEFACTION_RISK: { id: 'saturated_liquefaction_risk', label: 'Saturated Liquefaction Risk', maxTheta: 1.0, color: '#ef4444', badgeClass: 'bg-red-500/20 text-red-300 border-red-500/30' }
