  const val = Math.max(0, Number(ppvMmS) || 0);
  if (val < 2.5) return VIBRATION_RISK_TIERS.SAFE_AMBIENT;
  if (val < 10.0) return VIBRATION_RISK_TIERS.CAUTION_MONITORING;
