  HIGH_OCCLUSION_DEFICIT: { id: 'high_occlusion_deficit', label: 'High Occlusion Deficit (>= 25% Occlusion)', maxOcclusionPct: 100.0, color: '#ef4444', badgeClass: 'bg-red-500/20 text-red-300 border-red-500/30' }
